namespace SatlootLite {
 sealed class LineImportWindow:Form {
  readonly NodeStore library;TabControl tabs;TextBox text,url,server,port,user,password,name,errors;Picker protocol;DataGridView grid;Label status;Button preview,import;RouteBatch batch;bool busy;
  public LineImportWindow(NodeStore library,bool subscription=false){
   this.library=library;Text="导入线路 · SATLOOT Lite";Font=Theme.Font();BackColor=Theme.Bg;ClientSize=new Size(760,690);MinimumSize=new Size(690,610);StartPosition=FormStartPosition.CenterParent;ShowInTaskbar=false;
   var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=5,Padding=new Padding(20)};Controls.Add(layout);foreach(var h in new[]{245,38})layout.RowStyles.Add(new RowStyle(SizeType.Absolute,h));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,75));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,54));
   tabs=new TabControl{Dock=DockStyle.Fill};var paste=new TabPage("粘贴 / 文件");var subscriptionPage=new TabPage("订阅链接");var manual=new TabPage("手动代理");tabs.TabPages.AddRange(new[]{paste,subscriptionPage,manual});layout.Controls.Add(tabs,0,0);
   var pasteLayout=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=3,ColumnCount=1,Padding=new Padding(8)};pasteLayout.RowStyles.Add(new RowStyle(SizeType.Absolute,34));pasteLayout.RowStyles.Add(new RowStyle(SizeType.Percent,100));pasteLayout.RowStyles.Add(new RowStyle(SizeType.Absolute,32));paste.Controls.Add(pasteLayout);
   var toolbar=new FlowLayoutPanel{Dock=DockStyle.Fill};var clipboard=Theme.Button("从剪贴板粘贴");var file=Theme.Button("选择文本文件");clipboard.Height=file.Height=30;clipboard.Width=file.Width=160;toolbar.Controls.AddRange(new Control[]{clipboard,file});pasteLayout.Controls.Add(toolbar);
   text=new TextBox{Multiline=true,ScrollBars=ScrollBars.Both,Dock=DockStyle.Fill,MaxLength=2*1024*1024,WordWrap=false};pasteLayout.Controls.Add(text);var hint=Theme.Label("每行一条分享链接，或粘贴 Base64 订阅内容；最多 2 MB / 5000 条。",9,Theme.Muted);hint.Dock=DockStyle.Fill;pasteLayout.Controls.Add(hint);
   clipboard.Click+=(s,e)=>{try{if(Clipboard.ContainsText())text.Text=Clipboard.GetText();}catch{L.Show(this,"无法读取剪贴板，请直接粘贴。","导入线路",MessageBoxButtons.OK,MessageBoxIcon.Information);}};
   file.Click+=(s,e)=>{using(var dialog=new OpenFileDialog{Filter="线路文本 (*.txt)|*.txt|所有文件 (*.*)|*.*"}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;try{if(new FileInfo(dialog.FileName).Length>2*1024*1024)throw new Exception("文件超过 2 MB");text.Text=File.ReadAllText(dialog.FileName,new System.Text.UTF8Encoding(false,true));}catch{L.Show(this,"文件无法读取，请选择 2 MB 以内的 UTF-8 线路文本。","导入线路",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}};
   var subLayout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=3,Padding=new Padding(14)};subLayout.RowStyles.Add(new RowStyle(SizeType.Absolute,35));subLayout.RowStyles.Add(new RowStyle(SizeType.Absolute,40));subLayout.RowStyles.Add(new RowStyle(SizeType.Percent,100));subscriptionPage.Controls.Add(subLayout);subLayout.Controls.Add(Theme.Label("HTTPS 订阅链接"));url=new TextBox{Dock=DockStyle.Fill,UseSystemPasswordChar=true};subLayout.Controls.Add(url);var subHint=Theme.Label("点击「预览线路」读取订阅，确认后再导入。\n支持分享链接列表、Base64 文本；不支持 Clash YAML / JSON。\n订阅地址只用于本次读取，不会保存到线路库。",9,Theme.Muted);subHint.Dock=DockStyle.Fill;subLayout.Controls.Add(subHint);
   var fields=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=4,RowCount=3,Padding=new Padding(12)};fields.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,75));fields.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));fields.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,75));fields.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));manual.Controls.Add(fields);
   protocol=new Picker();protocol.Items.AddRange(new object[]{"HTTP","HTTPS","SOCKS5"});protocol.SelectedIndex=0;server=new TextBox();port=new TextBox{Text="7890"};user=new TextBox();password=new TextBox{UseSystemPasswordChar=true};name=new TextBox();AddField(fields,0,0,"协议",protocol);AddField(fields,2,0,"名称",name);AddField(fields,0,1,"服务器",server);AddField(fields,2,1,"端口",port);AddField(fields,0,2,"用户名",user);AddField(fields,2,2,"密码",password);
   status=Theme.Label("先预览，再将有效线路导入线路库。",9,Theme.Muted);status.Dock=DockStyle.Fill;layout.Controls.Add(status,0,1);grid=LineLibraryWindow.Grid();layout.Controls.Add(grid,0,2);errors=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BorderStyle=BorderStyle.None,BackColor=Theme.Bg};layout.Controls.Add(errors,0,3);
   var footer=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft,Padding=new Padding(0,10,0,0)};import=Theme.Button("导入有效线路",true);import.Enabled=false;preview=Theme.Button("预览线路");var cancel=Theme.Button("取消");footer.Controls.AddRange(new Control[]{import,preview,cancel});layout.Controls.Add(footer,0,4);cancel.DialogResult=DialogResult.Cancel;CancelButton=cancel;
   foreach(var c in new[]{text,url,server,port,user,password,name})c.TextChanged+=(s,e)=>InvalidatePreview();protocol.SelectedIndexChanged+=(s,e)=>InvalidatePreview();tabs.SelectedIndexChanged+=(s,e)=>InvalidatePreview();tabs.SelectedIndex=subscription?1:0;
   preview.Click+=async(s,e)=>await Preview();import.Click+=(s,e)=>{if(batch==null||busy)return;try{int count=library.Import(batch.Nodes);L.Show(this,"已导入 "+count+" 条线路，已有的重复线路已跳过。","导入完成",MessageBoxButtons.OK,MessageBoxIcon.Information);DialogResult=DialogResult.OK;Close();}catch(Exception ex){L.Show(this,ex.Message,"导入未完成",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};FormClosing+=(s,e)=>{if(busy)e.Cancel=true;};L.Apply(this);
  }
  static void AddField(TableLayoutPanel p,int col,int row,string label,Control field){if(col==0)p.RowStyles.Add(new RowStyle(SizeType.Percent,33));var caption=Theme.Label(label,9,Theme.Muted);caption.Dock=DockStyle.Fill;field.Dock=DockStyle.Fill;field.Margin=new Padding(3,16,12,14);p.Controls.Add(caption,col,row);p.Controls.Add(field,col+1,row);}
  void InvalidatePreview(){batch=null;if(import!=null)import.Enabled=false;if(grid!=null)grid.Rows.Clear();if(errors!=null)errors.Clear();}
  async Task Preview(){if(busy)return;busy=true;preview.Enabled=import.Enabled=false;tabs.Enabled=false;status.Text=L.T("正在读取并检查线路…");try{string content;if(tabs.SelectedIndex==1){string address=url.Text;content=await Task.Run(()=>NodeStore.Fetch(address));}else if(tabs.SelectedIndex==2){int number;if(!int.TryParse(port.Text,out number)||number<1||number>65535)throw new Exception("端口请填写 1–65535");var builder=new UriBuilder(protocol.SelectedItem.ToString().ToLowerInvariant(),server.Text.Trim(),number);builder.UserName=user.Text;builder.Password=password.Text;builder.Fragment=name.Text.Trim();content=builder.Uri.AbsoluteUri;}else content=text.Text;batch=await Task.Run(()=>NodeStore.Parse(content));grid.Rows.Clear();foreach(var n in batch.Nodes.Take(500))grid.Rows.Add(n.Name,n.Type.ToUpperInvariant(),n.Server);errors.Text=string.Join(Environment.NewLine,batch.Errors.Take(30));status.Text=L.T("有效线路：")+batch.Nodes.Count+L.T("；无效：")+batch.Errors.Count+L.T("；重复：")+batch.Duplicates+(batch.Nodes.Count>500?L.T("（列表仅展示前 500 条）"):"");import.Enabled=batch.Nodes.Count>0;}catch(Exception ex){batch=null;status.Text=L.T("预览未完成");L.Show(this,ex.Message,"导入线路",MessageBoxButtons.OK,MessageBoxIcon.Warning);}finally{busy=false;preview.Enabled=tabs.Enabled=true;}}
 }
 sealed class LineLibraryWindow:Form {
  readonly NodeStore library;readonly Action<RouteNode> choose;TextBox search;DataGridView grid;Label status;bool busy;Button test;
  public static DataGridView Grid(){var g=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AllowUserToResizeRows=false,RowHeadersVisible=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=true,BackgroundColor=Color.White,BorderStyle=BorderStyle.None,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,Font=Theme.Font(9),EnableHeadersVisualStyles=false};g.ColumnHeadersDefaultCellStyle.BackColor=Theme.Bg;g.ColumnHeadersDefaultCellStyle.ForeColor=Theme.Muted;g.DefaultCellStyle.SelectionBackColor=Theme.Pale;g.DefaultCellStyle.SelectionForeColor=Theme.Ink;g.RowTemplate.Height=34;g.Columns.Add("name",L.T("名称"));g.Columns.Add("type",L.T("协议"));g.Columns.Add("server",L.T("服务器"));g.Columns[0].FillWeight=45;g.Columns[1].FillWeight=20;g.Columns[2].FillWeight=35;return g;}
  public LineLibraryWindow(NodeStore library,Action<RouteNode> choose=null){this.library=library;this.choose=choose;Text="线路库 · SATLOOT Lite";Font=Theme.Font();BackColor=Theme.Bg;ClientSize=new Size(830,610);MinimumSize=new Size(760,560);StartPosition=FormStartPosition.CenterParent;ShowInTaskbar=false;
   var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=5,Padding=new Padding(24)};Controls.Add(layout);foreach(int h in new[]{50,48})layout.RowStyles.Add(new RowStyle(SizeType.Absolute,h));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,66));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,52));
   var toolbar=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};var paste=Theme.Button("导入线路",true);var sub=Theme.Button("订阅导入");test=Theme.Button("检测连接");var rename=Theme.Button("重命名");var remove=Theme.Button("删除线路");foreach(var b in new[]{paste,sub,test,rename,remove}){b.Width=130;toolbar.Controls.Add(b);}layout.Controls.Add(toolbar,0,0);search=new TextBox{Dock=DockStyle.Top,Margin=new Padding(0,6,0,10)};layout.Controls.Add(search,0,1);grid=Grid();layout.Controls.Add(grid,0,2);status=Theme.Label("选择线路后可检测连接；测试会通过该线路访问 Google 连通性检测地址。\n线路凭据在本机加密保存。删除线路库记录不会改变已经保存的环境网络。",9,Theme.Muted);status.Dock=DockStyle.Fill;layout.Controls.Add(status,0,3);
   var footer=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft};var use=Theme.Button("使用此线路",true);use.Visible=choose!=null;var close=Theme.Button("关闭");footer.Controls.AddRange(new Control[]{use,close});layout.Controls.Add(footer,0,4);close.Click+=(s,e)=>Close();CancelButton=close;search.TextChanged+=(s,e)=>RefreshRows();paste.Click+=(s,e)=>Import(false);sub.Click+=(s,e)=>Import(true);use.Click+=(s,e)=>Choose();grid.CellDoubleClick+=(s,e)=>{if(e.RowIndex>=0)Choose();};test.Click+=async(s,e)=>await Probe();
   rename.Click+=(s,e)=>{var n=Selected();if(n==null||busy)return;string value=TextPrompt.Ask(this,"重命名线路",n.Name);if(value==null)return;try{library.Rename(n.Id,value);RefreshRows();}catch(Exception ex){L.Show(this,ex.Message,"未保存",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};
   remove.Click+=(s,e)=>{if(busy)return;var ids=grid.SelectedRows.Cast<DataGridViewRow>().Select(r=>((RouteNode)r.Tag).Id).ToArray();if(ids.Length==0)return;if(L.Show(this,"从线路库删除 "+ids.Length+" 条线路？已保存的环境网络保持原样。","删除线路",MessageBoxButtons.OKCancel,MessageBoxIcon.Warning,MessageBoxDefaultButton.Button2)!=DialogResult.OK)return;try{library.Remove(ids);RefreshRows();}catch(Exception ex){L.Show(this,ex.Message,"删除未完成",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};FormClosing+=(s,e)=>{if(busy)e.Cancel=true;};RefreshRows();L.Apply(this);
  }
  void Import(bool subscription){if(busy)return;using(var form=new LineImportWindow(library,subscription))form.ShowDialog(this);RefreshRows();}
  RouteNode Selected(){return grid.CurrentRow==null?null:grid.CurrentRow.Tag as RouteNode;}
  void Choose(){if(busy||choose==null||Selected()==null)return;try{choose(Selected());DialogResult=DialogResult.OK;Close();}catch(Exception ex){L.Show(this,ex.Message,"未保存",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
  void RefreshRows(){grid.Rows.Clear();foreach(var n in library.Nodes.Where(n=>(n.Name+" "+n.Type+" "+n.Server).IndexOf(search.Text,StringComparison.CurrentCultureIgnoreCase)>=0)){int row=grid.Rows.Add(n.Name,n.Type.ToUpperInvariant(),n.Server);grid.Rows[row].Tag=n;}}
  async Task Probe(){var n=Selected();if(n==null||busy)return;busy=true;test.Enabled=false;status.Text=L.T("正在通过所选线路检测连接…");try{long ms=await Task.Run(()=>NodeStore.Probe(AppDomain.CurrentDomain.BaseDirectory,n));status.Text=n.Name+L.T("：连接成功，HTTP 响应耗时 ")+ms+" ms";}catch{status.Text=n.Name+L.T("：连接检测未通过，请核对节点、本机网络或更换线路。");}finally{busy=false;test.Enabled=true;}}
 }
 sealed class TextPrompt:Form {
  TextBox input;public string Value{get{return input.Text;}}
  TextPrompt(string title,string value){Text=L.T(title);Font=Theme.Font();BackColor=Theme.Bg;ClientSize=new Size(430,150);StartPosition=FormStartPosition.CenterParent;FormBorderStyle=FormBorderStyle.FixedDialog;ShowInTaskbar=false;MinimizeBox=MaximizeBox=false;input=new TextBox{Text=value,Bounds=new Rectangle(24,26,382,30),MaxLength=100};Controls.Add(input);var save=Theme.Button("保存环境",true);save.Text=L.T("确定");save.Location=new Point(274,82);save.DialogResult=DialogResult.OK;Controls.Add(save);var cancel=Theme.Button("取消");cancel.Location=new Point(132,82);cancel.DialogResult=DialogResult.Cancel;Controls.Add(cancel);AcceptButton=save;CancelButton=cancel;}
  public static string Ask(IWin32Window owner,string title,string value){using(var form=new TextPrompt(title,value))return form.ShowDialog(owner)==DialogResult.OK?form.Value:null;}
 }
